/*
 * ZyroPay Postgres schema (Neon). Conventions:
 *  - uuid primary keys generated by the application (UUIDv7 via IdGenerator); the DB
 *    default is only a fallback.
 *  - timestamps are `timestamptz`; every mutable table has created_at/updated_at.
 *  - token amounts: numeric(78,0) (uint256 range) read as strings; never floats.
 *  - USD amounts: numeric(38,0) USD cents.
 *  - secrets/tokens: only hashes are stored (sha256 hex), never the raw value.
 *  - enum values come from @zyropay/shared so the DB cannot drift from the contracts.
 */
import {
  AgentModeSchema,
  ApprovalStatusSchema,
  ChainFamilySchema,
  ChainTransactionStatusSchema,
  NETWORK_IDS,
  PolicyDecisionSchema,
  RequestSourceSchema,
  TX_REQUEST_STATES,
  type AgentPolicy,
  type CanonicalTransactionPayload,
  type JsonObject,
  type PluginManifest,
  type PolicyReason,
} from "@zyropay/shared";
import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  foreignKey,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

// ---------------------------------------------------------------------------
// Enums
// ---------------------------------------------------------------------------

/** Zod 4 `.options` is a plain array; pgEnum needs a non-empty tuple. */
function values<T extends string>(options: readonly T[]): [T, ...T[]] {
  const [first, ...rest] = options;
  if (first === undefined) throw new Error("enum must have at least one value");
  return [first, ...rest];
}

export const networkEnum = pgEnum("network", NETWORK_IDS);
export const chainFamilyEnum = pgEnum("chain_family", values(ChainFamilySchema.options));
export const txRequestStateEnum = pgEnum("tx_request_state", TX_REQUEST_STATES);
export const policyDecisionEnum = pgEnum("policy_decision", values(PolicyDecisionSchema.options));
export const approvalStatusEnum = pgEnum("approval_status", values(ApprovalStatusSchema.options));
export const chainTxStatusEnum = pgEnum(
  "chain_tx_status",
  values(ChainTransactionStatusSchema.options),
);
export const agentModeEnum = pgEnum("agent_mode", values(AgentModeSchema.options));
export const requesterTypeEnum = pgEnum("requester_type", ["user", "agent"]);
export const requestSourceEnum = pgEnum("request_source", values(RequestSourceSchema.options));
export const authProviderEnum = pgEnum("auth_provider", [
  "passkey",
  "email_otp",
  "oauth_google",
  "oauth_apple",
]);
export const tokenKindEnum = pgEnum("token_kind", [
  "access_token",
  "refresh_token",
  "authorization_code",
]);
export const reservationStatusEnum = pgEnum("reservation_status", [
  "active",
  "settled",
  "released",
]);
export const devicePlatformEnum = pgEnum("device_platform", ["ios", "android"]);
export const connectionStatusEnum = pgEnum("agent_connection_status", [
  "pending",
  "approved",
  "rejected",
  "expired",
]);
export const actorTypeEnum = pgEnum("actor_type", ["user", "agent", "system", "mcp", "webhook"]);
export const delegatedSignerStatusEnum = pgEnum("delegated_signer_status", [
  "pending",
  "active",
  "revoked",
]);

// ---------------------------------------------------------------------------
// Column helpers
// ---------------------------------------------------------------------------

const id = () => uuid("id").primaryKey().defaultRandom();
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());
const ts = (name: string) => timestamp(name, { withTimezone: true });
/** Token base units (uint256 range). Drizzle returns numeric as string. */
const baseUnits = (name: string) => numeric(name, { precision: 78, scale: 0 });
/** USD cents. */
const usdMinor = (name: string) => numeric(name, { precision: 38, scale: 0 });
const sha256HexCheck = (column: string) => sql.raw(`${column} ~ '^[0-9a-f]{64}$'`);

// ---------------------------------------------------------------------------
// Users & auth
// ---------------------------------------------------------------------------

export const users = pgTable(
  "users",
  {
    id: id(),
    email: text("email"),
    displayName: text("display_name"),
    /** One Turnkey sub-organization per user; the user's passkey is its root. */
    turnkeySubOrganizationId: text("turnkey_sub_organization_id").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: ts("deleted_at"),
  },
  (t) => [
    uniqueIndex("users_turnkey_sub_org_uq").on(t.turnkeySubOrganizationId),
    uniqueIndex("users_email_uq").on(sql`lower(${t.email})`),
  ],
);

export const authIdentities = pgTable(
  "auth_identities",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    provider: authProviderEnum("provider").notNull(),
    /** Passkey credential id, email address, or OIDC `sub`. */
    providerSubject: text("provider_subject").notNull(),
    /** Turnkey user id inside the sub-organization that owns this credential. */
    turnkeyUserId: text("turnkey_user_id"),
    createdAt: createdAt(),
    lastUsedAt: ts("last_used_at"),
  },
  (t) => [
    uniqueIndex("auth_identities_provider_subject_uq").on(t.provider, t.providerSubject),
    index("auth_identities_user_idx").on(t.userId),
  ],
);

/**
 * App sessions. Only the refresh-token hash is stored; access tokens are opaque random
 * tokens whose sha256 lives in session_access_tokens.
 */
export const sessions = pgTable(
  "sessions",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    refreshTokenHash: text("refresh_token_hash").notNull(),
    /** Previous session in the rotation chain (reuse of a rotated token revokes the chain). */
    rotatedFromId: uuid("rotated_from_id"),
    userAgent: text("user_agent"),
    createdAt: createdAt(),
    expiresAt: ts("expires_at").notNull(),
    revokedAt: ts("revoked_at"),
  },
  (t) => [
    uniqueIndex("sessions_refresh_token_hash_uq").on(t.refreshTokenHash),
    index("sessions_user_idx").on(t.userId),
    check("sessions_refresh_token_hash_ck", sha256HexCheck("refresh_token_hash")),
  ],
);

// ---------------------------------------------------------------------------
// Wallets
// ---------------------------------------------------------------------------

export const wallets = pgTable(
  "wallets",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    turnkeyWalletId: text("turnkey_wallet_id").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    /**
     * Set when the user removes (unlinks) the wallet in ZyroPay. Keys stay in Turnkey;
     * an archived wallet is invisible and unusable everywhere until it is created again.
     */
    archivedAt: ts("archived_at"),
  },
  (t) => [
    uniqueIndex("wallets_turnkey_wallet_uq").on(t.turnkeyWalletId),
    index("wallets_user_idx").on(t.userId),
  ],
);

export const walletAddresses = pgTable(
  "wallet_addresses",
  {
    id: id(),
    walletId: uuid("wallet_id")
      .notNull()
      .references(() => wallets.id, { onDelete: "cascade" }),
    family: chainFamilyEnum("family").notNull(),
    /** Canonical form: EIP-55 for EVM, base58 for Solana, lowercase bech32 for Cardano. */
    address: text("address").notNull(),
    derivationPath: text("derivation_path").notNull(),
    /**
     * Cardano only: the account's Ed25519 public key (lowercase hex). The enterprise address
     * carries only its hash, but signing (Turnkey `signWith`) and the vkey witness need the
     * key itself. Null for Solana/EVM (their address is the signer).
     */
    publicKey: text("public_key"),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("wallet_addresses_family_address_uq").on(t.family, t.address),
    index("wallet_addresses_wallet_idx").on(t.walletId),
  ],
);

/**
 * Read-only (watch) addresses. No keys, no Turnkey link: a separate table so no signing,
 * send, approval or agent path (which all load `wallets`) can ever receive one.
 */
export const watchWallets = pgTable(
  "watch_wallets",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    family: chainFamilyEnum("family").notNull(),
    /** The chain picked when adding it (display); balances cover the whole family. */
    network: networkEnum("network").notNull(),
    /** Canonical form: EIP-55 for EVM, base58 for Solana. */
    address: text("address").notNull(),
    /** Idempotency-Key of the create call: a retried create returns this row. */
    idempotencyKey: text("idempotency_key").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    removedAt: ts("removed_at"),
  },
  (t) => [
    // One live watch per (user, family, address); removed rows are history, so re-adding
    // an address later creates a fresh row.
    uniqueIndex("watch_wallets_user_family_address_uq")
      .on(t.userId, t.family, t.address)
      .where(sql`${t.removedAt} IS NULL`),
    uniqueIndex("watch_wallets_user_idempotency_uq").on(t.userId, t.idempotencyKey),
    index("watch_wallets_user_idx").on(t.userId, t.createdAt),
  ],
);

// ---------------------------------------------------------------------------
// Agents & OAuth
// ---------------------------------------------------------------------------

/** OAuth clients (MCP dynamic client registration), mirrored from the MCP worker. */
export const oauthClients = pgTable("oauth_clients", {
  /** OAuth `client_id`. */
  id: text("id").primaryKey(),
  clientName: text("client_name").notNull(),
  clientUri: text("client_uri"),
  logoUri: text("logo_uri"),
  redirectUris: jsonb("redirect_uris").$type<string[]>().notNull(),
  tokenEndpointAuthMethod: text("token_endpoint_auth_method").notNull(),
  /** Null for public clients (PKCE). */
  clientSecretHash: text("client_secret_hash"),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const agents = pgTable(
  "agents",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    oauthClientId: text("oauth_client_id").references(() => oauthClients.id, {
      onDelete: "set null",
    }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    lastUsedAt: ts("last_used_at"),
    revokedAt: ts("revoked_at"),
  },
  (t) => [index("agents_user_idx").on(t.userId)],
);

/**
 * Current policy per agent (1:1). Scalar fields are columns so limits can be queried;
 * list fields are jsonb validated by AgentPolicySchema on every read/write.
 * `version` is the optimistic-lock counter (UPDATE ... WHERE version = $expected).
 */
export const agentPolicies = pgTable(
  "agent_policies",
  {
    agentId: uuid("agent_id")
      .primaryKey()
      .references(() => agents.id, { onDelete: "cascade" }),
    mode: agentModeEnum("mode").notNull().default("always_ask"),
    spendingEnabled: boolean("spending_enabled").notNull().default(false),
    allowedWalletIds: jsonb("allowed_wallet_ids")
      .$type<AgentPolicy["allowedWalletIds"]>()
      .notNull(),
    allowedNetworks: jsonb("allowed_networks").$type<AgentPolicy["allowedNetworks"]>().notNull(),
    allowedTools: jsonb("allowed_tools").$type<AgentPolicy["allowedTools"]>().notNull(),
    restrictRecipients: boolean("restrict_recipients").notNull().default(true),
    recipientAllowlist: jsonb("recipient_allowlist")
      .$type<AgentPolicy["recipientAllowlist"]>()
      .notNull(),
    allowedProtocols: jsonb("allowed_protocols").$type<AgentPolicy["allowedProtocols"]>().notNull(),
    perTransactionUsdMinor: usdMinor("per_transaction_usd_minor").notNull().default("0"),
    dailyUsdMinor: usdMinor("daily_usd_minor").notNull().default("0"),
    monthlyUsdMinor: usdMinor("monthly_usd_minor").notNull().default("0"),
    overLimitBehavior: text("over_limit_behavior", { enum: ["require_approval", "deny"] })
      .notNull()
      .default("require_approval"),
    /** 0006: x402 payments valued above this (USD cents) must use Masumi escrow; null = off. */
    x402EscrowAboveUsdMinor: usdMinor("x402_escrow_above_usd_minor"),
    /** 0007: pay_x402 only to sellers with a verified Masumi registry identity. */
    requireRegisteredAgent: boolean("require_registered_agent").notNull().default(false),
    /** 0007: with requireRegisteredAgent, only these agentIdentifiers (empty = any registered). */
    trustedAgentIdentifiers: jsonb("trusted_agent_identifiers")
      .$type<string[]>()
      .notNull()
      .default([]),
    sessionExpiresAt: ts("session_expires_at"),
    revoked: boolean("revoked").notNull().default(false),
    version: integer("version").notNull().default(1),
    updatedAt: updatedAt(),
  },
  (t) => [
    check(
      "agent_policies_limits_nonneg_ck",
      sql`${t.perTransactionUsdMinor} >= 0 AND ${t.dailyUsdMinor} >= 0 AND ${t.monthlyUsdMinor} >= 0`,
    ),
    check(
      "agent_policies_x402_escrow_nonneg_ck",
      sql`${t.x402EscrowAboveUsdMinor} IS NULL OR ${t.x402EscrowAboveUsdMinor} >= 0`,
    ),
  ],
);

/**
 * Turnkey delegated (non-root) API-key user in a user's sub-organization, used ONLY for
 * autonomous agent signing (ADR-001). The private key is encrypted by the API with
 * DELEGATED_KEY_ENCRYPTION_KEY; Turnkey policies bound what it can sign.
 */
export const delegatedSigners = pgTable(
  "delegated_signers",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    turnkeyUserId: text("turnkey_user_id").notNull(),
    apiPublicKey: text("api_public_key").notNull(),
    /** AES-256-GCM ciphertext (base64: iv || ciphertext || tag). Never logged. */
    encryptedApiPrivateKey: text("encrypted_api_private_key").notNull(),
    turnkeyPolicyIds: jsonb("turnkey_policy_ids").$type<string[]>().notNull(),
    status: delegatedSignerStatusEnum("status").notNull().default("pending"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    revokedAt: ts("revoked_at"),
  },
  (t) => [
    uniqueIndex("delegated_signers_turnkey_user_uq").on(t.turnkeyUserId),
    // At most one live delegated signer per user (Turnkey policy count is limited).
    uniqueIndex("delegated_signers_user_active_uq")
      .on(t.userId)
      .where(sql`${t.status} <> 'revoked'`),
  ],
);

/** Device-code style agent connection: MCP authorize page shows `user_code`, app approves. */
export const agentConnections = pgTable(
  "agent_connections",
  {
    id: id(),
    userCode: text("user_code").notNull(),
    oauthClientId: text("oauth_client_id")
      .notNull()
      .references(() => oauthClients.id, { onDelete: "cascade" }),
    clientName: text("client_name").notNull(),
    clientUri: text("client_uri"),
    redirectUri: text("redirect_uri").notNull(),
    scopes: jsonb("scopes").$type<string[]>().notNull(),
    status: connectionStatusEnum("status").notNull().default("pending"),
    userId: uuid("user_id").references(() => users.id, { onDelete: "cascade" }),
    agentId: uuid("agent_id").references(() => agents.id, { onDelete: "set null" }),
    expiresAt: ts("expires_at").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("agent_connections_pending_code_uq")
      .on(t.userCode)
      .where(sql`${t.status} = 'pending'`),
  ],
);

export const oauthGrants = pgTable(
  "oauth_grants",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    agentId: uuid("agent_id")
      .notNull()
      .references(() => agents.id, { onDelete: "cascade" }),
    oauthClientId: text("oauth_client_id")
      .notNull()
      .references(() => oauthClients.id, { onDelete: "cascade" }),
    scopes: jsonb("scopes").$type<string[]>().notNull(),
    createdAt: createdAt(),
    revokedAt: ts("revoked_at"),
  },
  (t) => [
    index("oauth_grants_user_idx").on(t.userId),
    index("oauth_grants_agent_idx").on(t.agentId),
  ],
);

/** OAuth tokens and codes, by hash only. */
export const tokenRecords = pgTable(
  "token_records",
  {
    id: id(),
    grantId: uuid("grant_id")
      .notNull()
      .references(() => oauthGrants.id, { onDelete: "cascade" }),
    kind: tokenKindEnum("kind").notNull(),
    tokenHash: text("token_hash").notNull(),
    createdAt: createdAt(),
    expiresAt: ts("expires_at").notNull(),
    revokedAt: ts("revoked_at"),
  },
  (t) => [
    uniqueIndex("token_records_hash_uq").on(t.tokenHash),
    index("token_records_grant_idx").on(t.grantId),
    check("token_records_hash_ck", sha256HexCheck("token_hash")),
  ],
);

// ---------------------------------------------------------------------------
// Transaction requests, approvals, execution
// ---------------------------------------------------------------------------

export const transactionRequests = pgTable(
  "transaction_requests",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    walletId: uuid("wallet_id")
      .notNull()
      .references(() => wallets.id, { onDelete: "cascade" }),
    /** Agents are revoked, never hard-deleted while requests reference them (NO ACTION). */
    agentId: uuid("agent_id").references(() => agents.id),
    requesterType: requesterTypeEnum("requester_type").notNull(),
    source: requestSourceEnum("source").notNull(),
    network: networkEnum("network").notNull(),
    state: txRequestStateEnum("state").notNull().default("CREATED"),
    /** Immutable after creation. */
    payload: jsonb("payload").$type<CanonicalTransactionPayload>().notNull(),
    payloadHash: text("payload_hash").notNull(),
    idempotencyKey: text("idempotency_key").notNull(),
    valuationUsdMinor: usdMinor("valuation_usd_minor"),
    policyDecision: policyDecisionEnum("policy_decision"),
    policyReasons: jsonb("policy_reasons").$type<PolicyReason[]>().notNull().default([]),
    policyVersion: integer("policy_version"),
    /** Unsigned transaction exactly as built; signing requests must match it byte for byte. */
    unsignedTransaction: text("unsigned_transaction"),
    unsignedTransactionEncoding: text("unsigned_transaction_encoding", { enum: ["base64", "hex"] }),
    txHash: text("tx_hash"),
    failureReason: text("failure_reason"),
    simulated: boolean("simulated").notNull().default(false),
    expiresAt: ts("expires_at").notNull(),
    /** Optimistic lock: UPDATE ... SET version = version + 1 WHERE id = $1 AND version = $2. */
    version: integer("version").notNull().default(1),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("transaction_requests_user_idempotency_uq").on(t.userId, t.idempotencyKey),
    index("transaction_requests_state_expires_idx").on(t.state, t.expiresAt),
    index("transaction_requests_agent_created_idx").on(t.agentId, t.createdAt),
    index("transaction_requests_wallet_created_idx").on(t.walletId, t.createdAt),
    index("transaction_requests_payload_hash_idx").on(t.payloadHash),
    check("transaction_requests_payload_hash_ck", sha256HexCheck("payload_hash")),
    check(
      "transaction_requests_agent_requester_ck",
      sql`(${t.requesterType} = 'agent') = (${t.agentId} IS NOT NULL)`,
    ),
  ],
);

export const approvalRequests = pgTable(
  "approval_requests",
  {
    id: id(),
    transactionRequestId: uuid("transaction_request_id")
      .notNull()
      .references(() => transactionRequests.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    agentId: uuid("agent_id").references(() => agents.id, { onDelete: "set null" }),
    status: approvalStatusEnum("status").notNull().default("pending"),
    /** Must equal transaction_requests.payload_hash at decision time. */
    payloadHash: text("payload_hash").notNull(),
    expiresAt: ts("expires_at").notNull(),
    decidedAt: ts("decided_at"),
    rejectionReason: text("rejection_reason"),
    /** Turnkey activity id of the passkey-signed transaction (proof of approval). */
    turnkeyActivityId: text("turnkey_activity_id"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("approval_requests_tx_request_uq").on(t.transactionRequestId),
    index("approval_requests_user_status_idx").on(t.userId, t.status, t.createdAt),
    check("approval_requests_payload_hash_ck", sha256HexCheck("payload_hash")),
  ],
);

/** Transactions ZyroPay signed and broadcast. */
export const executedTransactions = pgTable(
  "executed_transactions",
  {
    id: id(),
    transactionRequestId: uuid("transaction_request_id")
      .notNull()
      .references(() => transactionRequests.id, { onDelete: "cascade" }),
    walletId: uuid("wallet_id")
      .notNull()
      .references(() => wallets.id, { onDelete: "cascade" }),
    network: networkEnum("network").notNull(),
    txHash: text("tx_hash").notNull(),
    status: chainTxStatusEnum("status").notNull().default("pending"),
    blockNumber: numeric("block_number", { precision: 20, scale: 0 }),
    feePaid: baseUnits("fee_paid"),
    turnkeyActivityId: text("turnkey_activity_id"),
    simulated: boolean("simulated").notNull().default(false),
    broadcastAt: ts("broadcast_at").notNull(),
    confirmedAt: ts("confirmed_at"),
    error: text("error"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("executed_transactions_network_hash_uq").on(t.network, t.txHash),
    uniqueIndex("executed_transactions_request_uq").on(t.transactionRequestId),
    index("executed_transactions_status_idx").on(t.status),
  ],
);

// ---------------------------------------------------------------------------
// Spending (per agent, USD cents)
// ---------------------------------------------------------------------------

/**
 * Holds created while a request is in flight. Policy evaluation counts
 * spent (ledger) + active reservations, inside the same DB transaction that inserts the
 * reservation (lock the agent_policies row FOR UPDATE), so concurrent requests serialize.
 */
export const spendingReservations = pgTable(
  "spending_reservations",
  {
    id: id(),
    agentId: uuid("agent_id")
      .notNull()
      .references(() => agents.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    transactionRequestId: uuid("transaction_request_id")
      .notNull()
      .references(() => transactionRequests.id, { onDelete: "cascade" }),
    amountUsdMinor: usdMinor("amount_usd_minor").notNull(),
    status: reservationStatusEnum("status").notNull().default("active"),
    createdAt: createdAt(),
    expiresAt: ts("expires_at").notNull(),
    resolvedAt: ts("resolved_at"),
  },
  (t) => [
    uniqueIndex("spending_reservations_request_uq").on(t.transactionRequestId),
    index("spending_reservations_agent_status_idx").on(t.agentId, t.status, t.createdAt),
    check("spending_reservations_amount_ck", sql`${t.amountUsdMinor} >= 0`),
  ],
);

/** Append-only record of settled agent spend (one row per broadcast request). */
export const spendingLedger = pgTable(
  "spending_ledger",
  {
    id: id(),
    agentId: uuid("agent_id")
      .notNull()
      .references(() => agents.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    transactionRequestId: uuid("transaction_request_id")
      .notNull()
      .references(() => transactionRequests.id, { onDelete: "cascade" }),
    amountUsdMinor: usdMinor("amount_usd_minor").notNull(),
    occurredAt: ts("occurred_at").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("spending_ledger_request_uq").on(t.transactionRequestId),
    index("spending_ledger_agent_time_idx").on(t.agentId, t.occurredAt),
    check("spending_ledger_amount_ck", sql`${t.amountUsdMinor} >= 0`),
  ],
);

// ---------------------------------------------------------------------------
// Plugins, notifications, webhooks, audit
// ---------------------------------------------------------------------------

export const plugins = pgTable("plugins", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  status: text("status", { enum: ["available", "coming_soon"] }).notNull(),
  riskCategory: text("risk_category", { enum: ["low", "medium", "high", "critical"] }).notNull(),
  manifest: jsonb("manifest").$type<PluginManifest>().notNull(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const userPluginSettings = pgTable(
  "user_plugin_settings",
  {
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    pluginId: text("plugin_id")
      .notNull()
      .references(() => plugins.id, { onDelete: "cascade" }),
    enabled: boolean("enabled").notNull().default(false),
    /** Non-secret per-user settings only. */
    config: jsonb("config").$type<JsonObject>().notNull().default({}),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.pluginId] })],
);

export const notificationDevices = pgTable(
  "notification_devices",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    expoPushToken: text("expo_push_token").notNull(),
    platform: devicePlatformEnum("platform").notNull(),
    deviceName: text("device_name"),
    createdAt: createdAt(),
    lastSeenAt: ts("last_seen_at"),
    disabledAt: ts("disabled_at"),
  },
  (t) => [
    uniqueIndex("notification_devices_token_uq").on(t.expoPushToken),
    index("notification_devices_user_idx").on(t.userId),
  ],
);

/** Inbound webhooks; UNIQUE(provider, event_id) makes processing idempotent. */
export const webhookEvents = pgTable(
  "webhook_events",
  {
    id: id(),
    provider: text("provider").notNull(),
    eventId: text("event_id").notNull(),
    eventType: text("event_type").notNull(),
    payload: jsonb("payload").$type<JsonObject>().notNull(),
    receivedAt: ts("received_at").notNull().defaultNow(),
    processedAt: ts("processed_at"),
    processingError: text("processing_error"),
    attempts: integer("attempts").notNull().default(0),
  },
  (t) => [
    uniqueIndex("webhook_events_provider_event_uq").on(t.provider, t.eventId),
    index("webhook_events_unprocessed_idx")
      .on(t.receivedAt)
      .where(sql`${t.processedAt} IS NULL`),
  ],
);

/** Append-only. The API role should be granted INSERT/SELECT only on this table. */
export const auditLogs = pgTable(
  "audit_logs",
  {
    id: id(),
    occurredAt: ts("occurred_at").notNull().defaultNow(),
    actorType: actorTypeEnum("actor_type").notNull(),
    actorId: text("actor_id"),
    userId: uuid("user_id").references(() => users.id, { onDelete: "set null" }),
    /** Dotted verb, e.g. "agent.policy.updated", "tx_request.approved". */
    action: text("action").notNull(),
    targetType: text("target_type"),
    targetId: text("target_id"),
    /** Correlation id of the HTTP request / MCP call. */
    requestId: text("request_id"),
    /** sha256 of client IP (salted); raw IPs are not stored. */
    ipHash: text("ip_hash"),
    /** Never secrets, tokens, or full payloads with PII. */
    metadata: jsonb("metadata").$type<JsonObject>().notNull().default({}),
  },
  (t) => [
    index("audit_logs_user_time_idx").on(t.userId, t.occurredAt),
    index("audit_logs_target_idx").on(t.targetType, t.targetId),
    index("audit_logs_action_time_idx").on(t.action, t.occurredAt),
  ],
);

// ---------------------------------------------------------------------------
// API runtime (migration 0001: sessions, rate limits, execution artifacts, push,
// incoming transfers, on-ramp orders)
// ---------------------------------------------------------------------------

/** Opaque access tokens (sha256 only). The refresh token lives in `sessions`. */
export const sessionAccessTokens = pgTable(
  "session_access_tokens",
  {
    id: id(),
    sessionId: uuid("session_id")
      .notNull()
      .references(() => sessions.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    tokenHash: text("token_hash").notNull(),
    createdAt: createdAt(),
    expiresAt: ts("expires_at").notNull(),
    revokedAt: ts("revoked_at"),
  },
  (t) => [
    uniqueIndex("session_access_tokens_hash_uq").on(t.tokenHash),
    index("session_access_tokens_session_idx").on(t.sessionId),
    check("session_access_tokens_hash_ck", sha256HexCheck("token_hash")),
  ],
);

/** One-time use of stamped login requests (a whoami body carries no timestamp). */
export const loginStampReplays = pgTable(
  "login_stamp_replays",
  {
    stampHash: text("stamp_hash").primaryKey(),
    createdAt: createdAt(),
    expiresAt: ts("expires_at").notNull(),
  },
  (t) => [
    index("login_stamp_replays_expires_idx").on(t.expiresAt),
    check("login_stamp_replays_hash_ck", sha256HexCheck("stamp_hash")),
  ],
);

/** Fixed-window rate-limit counters (atomic upsert per request). */
export const rateLimitCounters = pgTable(
  "rate_limit_counters",
  {
    bucketKey: text("bucket_key").notNull(),
    windowStart: ts("window_start").notNull(),
    count: integer("count").notNull().default(0),
  },
  (t) => [
    primaryKey({ name: "rate_limit_counters_pk", columns: [t.bucketKey, t.windowStart] }),
    index("rate_limit_counters_window_idx").on(t.windowStart),
  ],
);

export const SIGNING_KINDS = ["transaction", "typed_data"] as const;

/** Build/sign artifacts of a transaction request (signed bytes are kept for idempotent rebroadcast). */
export const transactionRequestArtifacts = pgTable(
  "transaction_request_artifacts",
  {
    transactionRequestId: uuid("transaction_request_id").primaryKey(),
    unsignedValidUntil: ts("unsigned_valid_until"),
    unsignedBuiltAt: ts("unsigned_built_at"),
    estimatedFee: baseUnits("estimated_fee"),
    signedTransaction: text("signed_transaction"),
    signedEncoding: text("signed_encoding", { enum: ["base64", "hex"] }),
    turnkeyActivityId: text("turnkey_activity_id"),
    signedAt: ts("signed_at"),
    broadcastAttempts: integer("broadcast_attempts").notNull().default(0),
    confirmAttempts: integer("confirm_attempts").notNull().default(0),
    updatedAt: ts("updated_at").notNull().defaultNow(),
    // --- 0002: real chain adapters --------------------------------------------------
    /** "transaction" (sign_transaction) or "typed_data" (sign_raw_payload over an EIP-712 digest). */
    signingKind: text("signing_kind", { enum: SIGNING_KINDS }).notNull().default("transaction"),
    /** Builder metadata needed later (Solana blockhash + lastValidBlockHeight, EVM nonce/fees). */
    unsignedMeta: jsonb("unsigned_meta").$type<JsonObject>(),
    /** EIP-712 typed data the user signs (x402 on EVM); the digest is unsigned_transaction. */
    typedData: jsonb("typed_data").$type<JsonObject>(),
    /** Nonce the API allocated to this EVM transaction (concurrent requests from one address). */
    evmNonce: integer("evm_nonce"),
    /** Hash derived from the signed bytes before broadcast, so a failed send can be reconciled. */
    expectedTxHash: text("expected_tx_hash"),
    // --- 0005: x402 delivery ----------------------------------------------------------
    /** When the MCP worker reported the paid retry of an x402 resource. */
    x402DeliveredAt: ts("x402_delivered_at"),
    /** HTTP status the resource answered the paid retry with. */
    x402HttpStatus: integer("x402_http_status"),
    /** The resource's settlement receipt as reported (display/audit only, never trusted). */
    x402Report: jsonb("x402_report").$type<JsonObject>(),
    // --- 0006: x402 Masumi escrow -----------------------------------------------------
    /**
     * Escrow lifecycle of a masumi pay_x402 request (services/escrow.ts): the current escrow
     * UTxO, the last chain read, and the buyer spend (refund request / withdrawal) in flight.
     */
    x402Escrow: jsonb("x402_escrow").$type<JsonObject>(),
  },
  (t) => [
    foreignKey({
      name: "transaction_request_artifacts_request_fk",
      columns: [t.transactionRequestId],
      foreignColumns: [transactionRequests.id],
    }).onDelete("cascade"),
    index("transaction_request_artifacts_evm_nonce_idx")
      .on(t.evmNonce)
      .where(sql`${t.evmNonce} IS NOT NULL`),
    check(
      "transaction_request_artifacts_signing_kind_ck",
      sql.raw(`signing_kind IN ('transaction', 'typed_data')`),
    ),
    check(
      "transaction_request_artifacts_encoding_ck",
      sql.raw(`signed_encoding IS NULL OR signed_encoding IN ('base64', 'hex')`),
    ),
  ],
);

export const NOTIFICATION_DISPATCH_STATUSES = ["pending", "sent", "failed"] as const;

/** Push dedupe: queue redelivery never sends the same notification twice. */
export const notificationDispatches = pgTable(
  "notification_dispatches",
  {
    dedupeKey: text("dedupe_key").primaryKey(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    kind: text("kind").notNull(),
    status: text("status", { enum: NOTIFICATION_DISPATCH_STATUSES }).notNull().default("pending"),
    attempts: integer("attempts").notNull().default(0),
    createdAt: createdAt(),
    sentAt: ts("sent_at"),
  },
  () => [
    check("notification_dispatches_status_ck", sql.raw(`status IN ('pending', 'sent', 'failed')`)),
  ],
);

/** Normalized incoming transfers from chain webhooks (Helius / Alchemy). */
export const incomingTransfers = pgTable(
  "incoming_transfers",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    walletId: uuid("wallet_id")
      .notNull()
      .references(() => wallets.id, { onDelete: "cascade" }),
    network: networkEnum("network").notNull(),
    txHash: text("tx_hash").notNull(),
    assetId: text("asset_id").notNull(),
    fromAddress: text("from_address"),
    toAddress: text("to_address").notNull(),
    amount: baseUnits("amount").notNull(),
    provider: text("provider").notNull(),
    webhookEventId: uuid("webhook_event_id").references(() => webhookEvents.id, {
      onDelete: "set null",
    }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("incoming_transfers_uq").on(t.network, t.txHash, t.toAddress, t.assetId),
    index("incoming_transfers_user_idx").on(t.userId, t.createdAt),
    check("incoming_transfers_amount_ck", sql.raw("amount >= 0")),
  ],
);

export const ONRAMP_ORDER_STATUSES = [
  "quoted",
  "session_created",
  "processing",
  "completed",
  "failed",
] as const;

export const onrampOrders = pgTable(
  "onramp_orders",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    walletId: uuid("wallet_id")
      .notNull()
      .references(() => wallets.id, { onDelete: "cascade" }),
    provider: text("provider").notNull(),
    quoteId: text("quote_id").notNull(),
    sessionId: text("session_id"),
    orderId: text("order_id"),
    network: networkEnum("network").notNull(),
    assetId: text("asset_id").notNull(),
    walletAddress: text("wallet_address").notNull(),
    status: text("status", { enum: ONRAMP_ORDER_STATUSES }).notNull().default("quoted"),
    simulated: boolean("simulated").notNull().default(false),
    quoteExpiresAt: ts("quote_expires_at").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("onramp_orders_provider_quote_uq").on(t.provider, t.quoteId),
    uniqueIndex("onramp_orders_provider_order_uq")
      .on(t.provider, t.orderId)
      .where(sql`${t.orderId} IS NOT NULL`),
    index("onramp_orders_user_idx").on(t.userId, t.createdAt),
    check(
      "onramp_orders_status_ck",
      sql.raw(`status IN ('quoted', 'session_created', 'processing', 'completed', 'failed')`),
    ),
  ],
);

/**
 * Short-lived provider credentials shared by every isolate (e.g. the Transak partner
 * access token: refreshing it invalidates the previous one, so isolates must share it).
 * The value is AES-256-GCM encrypted with DELEGATED_KEY_ENCRYPTION_KEY (AAD = provider).
 */
export const providerCredentials = pgTable("provider_credentials", {
  provider: text("provider").primaryKey(),
  encryptedValue: text("encrypted_value").notNull(),
  expiresAt: ts("expires_at"),
  updatedAt: updatedAt(),
});

// ---------------------------------------------------------------------------
// Auto-pay on Cardano: the agent's on-chain allowance (docs/AUTOPAY.md, migration 0008)
// ---------------------------------------------------------------------------

/**
 * One allowance per agent at the owner's allowance contract. The limits are enforced by the
 * Cardano ledger (contracts/allowance); these rows only remember what ZyroPay built, the
 * server-held agent key (AES-256-GCM, never logged) and the owner action awaiting the passkey.
 */
export const cardanoAllowances = pgTable(
  "cardano_allowances",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    agentId: uuid("agent_id")
      .notNull()
      .references(() => agents.id, { onDelete: "cascade" }),
    walletId: uuid("wallet_id")
      .notNull()
      .references(() => wallets.id, { onDelete: "cascade" }),
    network: networkEnum("network").notNull(),
    /** AllowanceStatus (@zyropay/shared ALLOWANCE_STATUSES). */
    status: text("status").notNull(),
    ownerAddress: text("owner_address").notNull(),
    ownerKeyHash: text("owner_key_hash").notNull(),
    ownerPublicKey: text("owner_public_key").notNull(),
    scriptAddress: text("script_address").notNull(),
    agentAddress: text("agent_address").notNull(),
    agentKeyHash: text("agent_key_hash").notNull(),
    agentPublicKey: text("agent_public_key").notNull(),
    /** AES-256-GCM (base64) of the agent's Ed25519 seed; "destroyed" once revoked. */
    encryptedAgentKey: text("encrypted_agent_key").notNull(),
    /** The datum the create wrote (AllowanceDatumView, decimal strings). */
    datum: jsonb("datum").$type<JsonObject>().notNull(),
    /** Payee addresses as the user gave them (null = any payee). */
    payeeAddresses: jsonb("payee_addresses").$type<string[] | null>(),
    /** Fiat limits as given, with the price used (null = given in lovelace). */
    fiat: jsonb("fiat").$type<JsonObject | null>(),
    budgetLovelace: baseUnits("budget_lovelace").notNull(),
    floatLovelace: baseUnits("float_lovelace").notNull(),
    /** The owner transaction built for the passkey (create / top_up / revoke), or null. */
    pendingAction: jsonb("pending_action").$type<JsonObject | null>(),
    createTxHash: text("create_tx_hash"),
    lastTxHash: text("last_tx_hash"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    revokedAt: ts("revoked_at"),
  },
  (t) => [
    // At most one live allowance per agent.
    uniqueIndex("cardano_allowances_agent_live_uq")
      .on(t.agentId)
      .where(sql`${t.status} not in ('revoked', 'failed')`),
    index("cardano_allowances_user_idx").on(t.userId),
  ],
);

/** A payment the agent key made from an allowance (one per transaction request). */
export const cardanoAllowanceSpends = pgTable(
  "cardano_allowance_spends",
  {
    id: id(),
    allowanceId: uuid("allowance_id")
      .notNull()
      .references(() => cardanoAllowances.id, { onDelete: "cascade" }),
    transactionRequestId: uuid("transaction_request_id")
      .notNull()
      .references(() => transactionRequests.id, { onDelete: "cascade" }),
    payee: text("payee").notNull(),
    lovelace: baseUnits("lovelace").notNull(),
    txHash: text("tx_hash"),
    /** The allowance UTxO spent (`<tx>#<i>`) and the continuing datum (AllowanceDatumView). */
    spentUtxo: text("spent_utxo"),
    nextDatum: jsonb("next_datum").$type<JsonObject | null>(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("cardano_allowance_spends_request_uq").on(t.transactionRequestId),
    index("cardano_allowance_spends_allowance_idx").on(t.allowanceId, t.createdAt),
  ],
);
